window.docContents[189].resolve({"/Elementary-Functions/___4___47-Approximations/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___47-Approximations--___4___47-Approximations":{"contents":"DLMF §4.47 is a bibliography of approximation resources for elementary\nfunctions. It has four subsections and no numbered formulas: the references\nprovide coefficient tables, rational approximants, Padé approximants, and\nadditional bibliographic guidance. The available precision and the list of\nfunctions depend on the cited source, so this page records those scopes rather\nthan introducing unsupported approximation formulas or error bounds.\n\n\n\n\n\n\n\n\n\n","context":"LMLF · DLMF with Lean\u0009Elementary Functions\u0009§4.47 Approximations","header":"§4.47 Approximations","id":"/Elementary-Functions/___4___47-Approximations/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___47-Approximations--___4___47-Approximations"}});